CREATE UNIQUE INDEX IF NOT EXISTS "categories_family_key_uidx" ON "ledger"."categories" USING btree ("family_id","key");--> statement-breakpoint
UPDATE "ledger"."categories" SET "icon" = CASE "icon" WHEN '🛒' THEN 'bag' WHEN '🏠' THEN 'home' WHEN '💡' THEN 'bolt' WHEN '🔥' THEN 'flame' WHEN '🚰' THEN 'drop' WHEN '📶' THEN 'wifi' WHEN '📱' THEN 'phone' WHEN '🛺' THEN 'ride' WHEN '📚' THEN 'school' WHEN '💊' THEN 'pulse' WHEN '🧹' THEN 'helper' WHEN '👕' THEN 'shirt' WHEN '🍛' THEN 'plate' WHEN '🤝' THEN 'hands' WHEN '🕌' THEN 'heart' WHEN '🎉' THEN 'gift' WHEN '🎁' THEN 'gift' WHEN '🧺' THEN 'basket' WHEN '🧴' THEN 'comb' WHEN '🎬' THEN 'film' WHEN '🏦' THEN 'bank' WHEN '🧾' THEN 'receipt' WHEN '📦' THEN 'box' WHEN '💼' THEN 'wallet' WHEN '🏪' THEN 'shop' WHEN '✈️' THEN 'plane' WHEN '🏘️' THEN 'key' WHEN '💰' THEN 'wallet' ELSE 'dots' END WHERE "icon" IS NOT NULL AND "icon" NOT IN ('bag', 'home', 'bolt', 'flame', 'drop', 'wifi', 'phone', 'ride', 'school', 'pulse', 'helper', 'shirt', 'plate', 'hands', 'heart', 'gift', 'basket', 'comb', 'film', 'bank', 'receipt', 'box', 'wallet', 'shop', 'plane', 'key', 'dots');
